"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * ACTIVITY HEATMAP: every day as a square, weeks across
 *
 *   arrive    the first time it's on screen the days fill in
 *             as a wave from the oldest week to the newest, and
 *             the total rolls up from zero
 *   point     point at a day (or move to it with the arrow keys)
 *             and one readout glides along the rail above the
 *             grid to its week: the count rolls, the date morphs.
 *             At rest the readout sits on the busiest day
 *   level     point at a step of the legend and every day
 *             outside that band steps back
 *   data      new numbers or a new colour ripple across the grid
 *             week by week instead of switching at once
 *   fit       it shows as many of the weeks as fit at a readable
 *             size, newest on the right
 *
 * The grid is a real ARIA grid: one tab stop, arrow keys, Home
 * and End, and each day's count and date as its label.
 * ───────────────────────────────────────────────────────── */

export interface HeatmapDay {
  /** "YYYY-MM-DD". Days missing from the data count as zero. */
  date: string;
  value: number;
}

export interface ActivityHeatmapProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  data: HeatmapDay[];
  /** The last day shown, "YYYY-MM-DD"; defaults to the latest day in the data. */
  end?: string;
  /** The most weeks to show; fewer when the card is narrow. */
  weeks?: number;
  /** The first row: 0 for Sunday, 1 for Monday. */
  weekStart?: 0 | 1;
  /** What's being counted, e.g. { one: "order", other: "orders" }. */
  unit?: { one: string; other: string };
  /** The colour of the busiest days; the other steps are mixed from it. */
  color?: string;
  /** Lower bounds of levels 1 to 4. By default they come from the data's own quartiles. */
  thresholds?: [number, number, number, number];
  title?: React.ReactNode;
  description?: React.ReactNode;
  action?: React.ReactNode;
  locales?: string | string[];
  onDayClick?: (day: HeatmapDay) => void;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DAY = 86_400_000;
const GAP = 3;
const MIN_CELL = 10;
const MAX_CELL = 16;
const LABELS = 30;
const UNIT = { one: "contribution", other: "contributions" };
const MIX = [0, 28, 52, 76, 100];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );
const subscribeNothing = () => () => {};
/** Dates in the visitor's language wait for hydration, so the server's en-US render and the first client render match. */
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );

const parse = (date: string) => Date.parse(`${date}T00:00:00Z`);
const iso = (t: number) => new Date(t).toISOString().slice(0, 10);

/** The quartiles of the days that have anything, as the lower bounds of levels 2 to 4 (level 1 is anything above zero). */
function quartiles(values: number[]): [number, number, number, number] {
  const sorted = values.filter((v) => v > 0).sort((a, b) => a - b);
  if (!sorted.length) return [1, 2, 3, 4];
  const at = (q: number) =>
    sorted[Math.min(sorted.length - 1, Math.floor(q * sorted.length))];
  return [Number.MIN_VALUE, at(0.25), at(0.5), at(0.75)];
}

const levelOf = (v: number, t: [number, number, number, number]) =>
  v <= 0
    ? 0
    : v >= t[3]
      ? 4
      : v >= t[2]
        ? 3
        : v >= t[1]
          ? 2
          : v >= t[0]
            ? 1
            : 0;

export function ActivityHeatmap({
  data,
  end,
  weeks = 26,
  weekStart = 0,
  unit = UNIT,
  color = "var(--chart-3, #1baf7a)",
  thresholds,
  title,
  description,
  action,
  locales,
  onDayClick,
  className = "",
  ...props
}: ActivityHeatmapProps) {
  const reduced = useReducedMotion();
  const hydrated = useHydrated();
  const lang = hydrated ? locales : (locales ?? "en-US");
  const rootRef = React.useRef<HTMLDivElement>(null);
  const bodyRef = React.useRef<HTMLDivElement>(null);
  const pillRef = React.useRef<HTMLDivElement>(null);
  const cellRefs = React.useRef(new Map<string, HTMLElement>());
  const [width, setWidth] = React.useState(0);
  const [pillWidth, setPillWidth] = React.useState(0);
  const [visible, setVisible] = React.useState(false);
  const [pointed, setPointed] = React.useState<string | null>(null);
  const [focused, setFocused] = React.useState<string | null>(null);
  const [band, setBand] = React.useState<number | null>(null);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -10% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Measured before the first paint, so the grid never shows at the wrong size.
  React.useLayoutEffect(() => {
    const el = bodyRef.current;
    if (!el) return;
    const observer = new ResizeObserver(([entry]) => {
      const w = Math.floor(entry.contentRect.width);
      setWidth((prev) => (prev === w ? prev : w));
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useEffect(() => {
    const el = pillRef.current;
    if (!el) return;
    const observer = new ResizeObserver(() => {
      const w = el.offsetWidth;
      setPillWidth((prev) => (prev === w ? prev : w));
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // The weeks that fit: at least MIN_CELL a day, never more than asked for.
  const room = Math.max(0, width - LABELS);
  const shown = width
    ? Math.max(4, Math.min(weeks, Math.floor((room + GAP) / (MIN_CELL + GAP))))
    : weeks;
  const cell = width
    ? Math.min(MAX_CELL, (room + GAP) / shown - GAP)
    : MAX_CELL;
  const gridWidth = shown * (cell + GAP) - GAP;

  const values = new Map<string, number>();
  for (const d of data) values.set(d.date, (values.get(d.date) ?? 0) + d.value);
  const lastDate =
    end ??
    data.reduce(
      (latest, d) => (d.date > latest ? d.date : latest),
      data[0]?.date ?? "",
    );
  const last = lastDate ? parse(lastDate) : 0;
  const lastRow = last ? (new Date(last).getUTCDay() - weekStart + 7) % 7 : 0;
  const first = last - ((shown - 1) * 7 + lastRow) * DAY;

  // Columns are weeks, rows are weekdays; days after the last one are left out.
  const grid = Array.from({ length: 7 }, (_, row) =>
    Array.from({ length: shown }, (_, col) => {
      const t = first + (col * 7 + row) * DAY;
      const date = iso(t);
      return {
        date,
        t,
        row,
        col,
        value: values.get(date) ?? 0,
        future: t > last,
      };
    }),
  );
  // In date order (the grid itself runs row by row).
  const days = grid
    .flat()
    .filter((d) => !d.future && last)
    .sort((a, b) => a.t - b.t);
  const levels = thresholds ?? quartiles(days.map((d) => d.value));
  const total = days.reduce((sum, d) => sum + d.value, 0);
  const peak = days.reduce<(typeof days)[number] | null>(
    (best, d) => (!best || d.value > best.value ? d : best),
    null,
  );

  const current =
    days.find((d) => d.date === (pointed ?? focused)) ??
    (peak && peak.value > 0 ? peak : null);
  const named = (n: number) => (n === 1 ? unit.one : unit.other);
  const dayLabel = (t: number, long = false) =>
    new Intl.DateTimeFormat(lang, {
      timeZone: "UTC",
      weekday: long ? "long" : "short",
      day: "numeric",
      month: long ? "long" : "short",
    }).format(t);
  const month = (t: number) =>
    new Intl.DateTimeFormat(lang, { timeZone: "UTC", month: "short" }).format(
      t,
    );
  const weekday = (row: number) =>
    new Intl.DateTimeFormat(lang, { timeZone: "UTC", weekday: "short" }).format(
      Date.UTC(2026, 0, 4 + ((row + weekStart) % 7)),
    );

  // A month's name over the first week that starts in it, if there's room before the next.
  const months: { col: number; label: string }[] = [];
  for (let col = 0; col < shown; col++) {
    const t = grid[0][col].t;
    const prev = col > 0 ? grid[0][col - 1].t : null;
    if (
      prev === null
        ? new Date(t).getUTCDate() <= 7
        : new Date(t).getUTCMonth() !== new Date(prev).getUTCMonth()
    ) {
      if (!months.length || col - months[months.length - 1].col >= 3)
        months.push({ col, label: month(t) });
    }
  }

  const x = current ? LABELS + current.col * (cell + GAP) + cell / 2 : LABELS;
  const half = pillWidth / 2;
  const pillX = Math.min(
    Math.max(x, half),
    Math.max(half, LABELS + gridWidth - half),
  );

  const fill = (level: number) =>
    level === 0
      ? "color-mix(in oklab, var(--foreground) 7%, transparent)"
      : `color-mix(in oklab, ${color} ${MIX[level]}%, var(--background))`;

  const move = (date: string) => {
    setFocused(date);
    cellRefs.current.get(date)?.focus();
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    const at =
      days.find((d) => d.date === focused) ?? peak ?? days[days.length - 1];
    if (!at) return;
    const steps: Record<string, number> = {
      ArrowLeft: -7,
      ArrowRight: 7,
      ArrowUp: -1,
      ArrowDown: 1,
    };
    let next: number | null = null;
    if (e.key in steps) next = at.t + steps[e.key] * DAY;
    else if (e.key === "Home") next = days[0]?.t ?? null;
    else if (e.key === "End") next = days[days.length - 1]?.t ?? null;
    else if ((e.key === "Enter" || e.key === " ") && onDayClick) {
      e.preventDefault();
      onDayClick({ date: at.date, value: at.value });
      return;
    }
    if (next === null) return;
    e.preventDefault();
    if (next >= (days[0]?.t ?? 0) && next <= last) move(iso(next));
  };

  const wave = (col: number) =>
    reduced
      ? "none"
      : `background-color 520ms ${EASE} ${col * 16}ms, opacity 200ms ${EASE}, box-shadow 160ms ${EASE}`;
  const tabStop = focused ?? current?.date ?? days[days.length - 1]?.date;

  return (
    <div
      ref={rootRef}
      className={`w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      {/* Its natural width where the parent sizes to its content (a centred flex column), without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 640px)" }}
      />
      <div className="@container w-full">
        <div className="p-4 @md:p-5">
          {(title || description || action) && (
            <div className="mb-3 flex items-start justify-between gap-3">
              <div className="min-w-0">
                {title && (
                  <p className="text-[13.5px] font-medium text-foreground @md:text-[14px]">
                    {title}
                  </p>
                )}
                {description && (
                  <p className="mt-0.5 text-[12px] text-muted-foreground @md:text-[12.5px]">
                    {description}
                  </p>
                )}
              </div>
              {action && <div className="shrink-0">{action}</div>}
            </div>
          )}

          <p className="flex flex-wrap items-baseline gap-x-1.5 text-[12px] text-muted-foreground @md:text-[12.5px]">
            <span className="text-[22px] font-semibold tracking-[-0.03em] text-foreground tabular-nums @md:text-[26px]">
              <NumberRoll
                value={visible ? total : 0}
                locales={locales}
                duration={1000}
              />
            </span>
            <span>
              {named(total)} in the last {shown} weeks
            </span>
          </p>

          <div
            ref={bodyRef}
            className="relative mt-3 w-full"
            onPointerLeave={() => setPointed(null)}
          >
            {/* The readout: one pill that glides to the day being pointed at, or rests on the busiest one. */}
            <div className="relative h-7">
              <div
                ref={pillRef}
                aria-hidden="true"
                className="absolute left-0 top-0 flex h-6 items-center gap-1.5 whitespace-nowrap rounded-full bg-foreground px-2.5 text-[11.5px] text-background"
                style={{
                  transform: `translateX(${pillX - half}px)`,
                  opacity: current && width ? 1 : 0,
                  transition: reduced
                    ? "none"
                    : `transform 300ms ${EASE}, opacity 200ms ${EASE}`,
                }}
              >
                <span className="font-medium tabular-nums">
                  <NumberRoll
                    value={current?.value ?? 0}
                    locales={locales}
                    duration={600}
                  />
                </span>
                <span className="opacity-70">
                  <TextMorph
                    duration={360}
                  >{`${named(current?.value ?? 0)} · ${current ? dayLabel(current.t) : ""}`}</TextMorph>
                </span>
              </div>
            </div>

            {/* Month names over the weeks they start in. */}
            <div
              aria-hidden="true"
              className="relative h-4 text-[10.5px] text-muted-foreground @md:text-[11px]"
              style={{ marginLeft: LABELS }}
            >
              {months.map((m) => (
                <span
                  key={m.col}
                  className="absolute top-0"
                  style={{ left: m.col * (cell + GAP) }}
                >
                  {m.label}
                </span>
              ))}
            </div>

            <div className="mt-1 flex">
              <div
                aria-hidden="true"
                className="grid shrink-0 text-[10.5px] text-muted-foreground @md:text-[11px]"
                style={{
                  width: LABELS,
                  gridTemplateRows: `repeat(7, ${cell}px)`,
                  rowGap: GAP,
                }}
              >
                {Array.from({ length: 7 }, (_, row) => (
                  <span
                    key={row}
                    className="leading-none"
                    style={{ lineHeight: `${cell}px` }}
                  >
                    {(
                      weekStart === 0 ? row % 2 === 1 : row % 2 === 0 && row < 6
                    )
                      ? weekday(row)
                      : ""}
                  </span>
                ))}
              </div>

              <div
                role="grid"
                aria-label={`${total} ${named(total)} in the last ${shown} weeks`}
                aria-readonly="true"
                onKeyDown={onKeyDown}
                onBlur={(e) => {
                  if (!e.currentTarget.contains(e.relatedTarget as Node | null))
                    setFocused(null);
                }}
                className="grid"
                style={{
                  width: gridWidth,
                  gridTemplateColumns: `repeat(${shown}, ${cell}px)`,
                  gridTemplateRows: `repeat(7, ${cell}px)`,
                  gap: GAP,
                }}
              >
                {grid.map((row, r) => (
                  <div key={r} role="row" className="contents">
                    {row.map((d) => {
                      const level = levelOf(d.value, levels);
                      const on = (pointed ?? focused) === d.date;
                      const out = band !== null && level !== band;
                      return (
                        <span
                          key={d.date}
                          ref={(el) => {
                            if (el) cellRefs.current.set(d.date, el);
                            else cellRefs.current.delete(d.date);
                          }}
                          role="gridcell"
                          aria-label={
                            d.future
                              ? undefined
                              : `${d.value} ${named(d.value)}, ${dayLabel(d.t, true)}`
                          }
                          aria-hidden={d.future || undefined}
                          tabIndex={!d.future && d.date === tabStop ? 0 : -1}
                          onPointerEnter={(e) =>
                            e.pointerType === "mouse" &&
                            !d.future &&
                            setPointed(d.date)
                          }
                          onPointerDown={(e) =>
                            e.pointerType !== "mouse" &&
                            !d.future &&
                            setPointed(d.date)
                          }
                          onFocus={() => setFocused(d.date)}
                          onClick={() =>
                            !d.future &&
                            onDayClick?.({ date: d.date, value: d.value })
                          }
                          className={`rounded-[3px] outline-none focus-visible:ring-2 focus-visible:ring-ring/50 ${onDayClick && !d.future ? "cursor-pointer" : ""}`}
                          style={{
                            gridColumn: d.col + 1,
                            gridRow: r + 1,
                            visibility: d.future ? "hidden" : undefined,
                            background: fill(visible ? level : 0),
                            opacity: out ? 0.22 : 1,
                            boxShadow: on
                              ? "inset 0 0 0 1.5px var(--foreground)"
                              : undefined,
                            transition: wave(d.col),
                          }}
                        />
                      );
                    })}
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* The scale: point at a step to see only the days in it. */}
          <div
            className="mt-3 flex items-center justify-end gap-1.5 text-[11px] text-muted-foreground"
            onPointerLeave={() => setBand(null)}
          >
            <span>Less</span>
            {[0, 1, 2, 3, 4].map((level) => (
              <span
                key={level}
                aria-hidden="true"
                onPointerEnter={() => setBand(level)}
                className="size-[11px] cursor-default rounded-[3px] transition-[box-shadow] duration-150"
                style={{
                  background: fill(level),
                  boxShadow:
                    band === level
                      ? "0 0 0 1.5px var(--foreground)"
                      : undefined,
                  transition: reduced
                    ? "none"
                    : `background-color 520ms ${EASE}`,
                }}
              />
            ))}
            <span>More</span>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

